import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate, uint256 mtFeeBase, uint256 mtFeeQuote, uint256 baseBalance, uint256 quoteBalance) public {
        mtFeeRate = bound(mtFeeRate, 0, 1e18);
        mtFeeBase = bound(mtFeeBase, 0, 1e12);
        mtFeeQuote = bound(mtFeeQuote, 0, 1e12);
        baseBalance = bound(baseBalance, 0, 1e12);
        quoteBalance = bound(quoteBalance, 0, 1e12);

        // Mint initial tokens to create reserves via buyShares
        vm.deal(address(this), 1 ether);
        // Deploy mock tokens
        IERC20 baseToken = IERC20(address(new ERC20Mock("Base", "BASE")));
        IERC20 quoteToken = IERC20(address(new ERC20Mock("Quote", "QUOTE")));

        // Initialize vault (simplified: we need to set up state via the contract)
        // For testing the bug, we can directly manipulate state using prank

        // First, we need to ensure base and quote tokens exist
        // Use vm.mockCall to simulate token balances
        // Instead, we can deploy a full setup

        // Since we can't interact with internal state directly, we call adjustMtFeeRate
        // and then check the invariant via public getters

        c.adjustMtFeeRate(mtFeeRate);

        // After adjustMtFeeRate, the base reserve should equal base balance - mt fee base
        // We can check this by calling getVaultReserve and getMtFeeTotal
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();
        (uint256 mtFeeBaseTotal, uint256 mtFeeQuoteTotal) = c.getMtFeeTotal();
        uint256 baseBalanceActual = IERC20(c._BASE_TOKEN_()).balanceOf(address(c)) - mtFeeBaseTotal;

        assertTrue(baseReserve == baseBalanceActual, "BASE_RESERVE not synced");
    }
}

// Minimal ERC20 mock for testing (not part of C, but needed for the test to compile)
contract ERC20Mock {
    string public name;
    string public symbol;
    uint8 public decimals = 18;
    mapping(address => uint256) public balanceOf;

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

