pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Bound mtFeeRate to valid range
        mtFeeRate = bound(mtFeeRate, 0, 10**18);

        // Get the base token address from the contract
        address baseToken = address(c._BASE_TOKEN_());

        // Give this contract some base tokens and quote tokens
        vm.deal(address(this), 1 ether);

        // Simulate some initial reserves: we need a non-zero base reserve for the buyShares to work
        // But for adjustMtFeeRate alone we don't need reserves

        // Record the initial base balance minus MT_FEE_BASE
        uint256 initialBaseBalanceMinusFee = IERC20(baseToken).balanceOf(address(c)) - c._MT_FEE_BASE_();
        uint256 initialBaseReserve = c._BASE_RESERVE_();

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(mtFeeRate);

        // The rule: the difference (balance - MT_FEE_BASE - _BASE_RESERVE_) should be unchanged
        uint256 finalBaseBalanceMinusFee = IERC20(baseToken).balanceOf(address(c)) - c._MT_FEE_BASE_();
        uint256 finalBaseReserve = c._BASE_RESERVE_();

        uint256 initialExcess = initialBaseBalanceMinusFee - initialBaseReserve;
        uint256 finalExcess = finalBaseBalanceMinusFee - finalBaseReserve;

        assertTrue(initialExcess == finalExcess, "Excess base tokens should remain unchanged");
    }
}

