pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        vm.assume(mtFeeRate <= 10**18);

        // Get initial state
        uint256 baseReserveBefore = c._BASE_RESERVE_();
        uint256 mtFeeBaseBefore = c._MT_FEE_BASE_();

        // Adjust mt fee rate
        c.adjustMtFeeRate(mtFeeRate);

        // After adjustment, compute the "excess" base balance
        uint256 baseBalance = c._BASE_TOKEN_().balanceOf(address(c));
        uint256 mtFeeBaseAfter = c._MT_FEE_BASE_();
        uint256 baseReserveAfter = c._BASE_RESERVE_();
        uint256 excess = baseBalance - mtFeeBaseAfter - baseReserveAfter;

        // The excess should equal the excess before the call (which is 0 since no deposit happened)
        assertTrue(excess == 0, "Base balance invariant violated");
    }
}

