// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Restrict mtFeeRate to valid range as in adjustMtFeeRate require: mtFeeRate <= 10**18
        vm.assume(mtFeeRate <= 10**18);

        // Perform any sequence of public calls that do not change _QUOTE_RESERVE_.
        // Example: call adjustPriceLimit (doesn't change quote reserve)
        // But first we need to set maintainer to avoid revert.
        // We can use the onlyMaintainer modifier; we prank as the maintainer.
        // However, _MAINTAINER_ is initially address(0) (default). So we need to set it.
        // Since we cannot set _MAINTAINER_ externally, we can instead call functions that don't require maintainer.
        // Actually, adjustMtFeeRate requires maintainer. But the invariant test must end with adjustMtFeeRate.
        // We can use prank on the maintainer. We'll assume we can set maintainer via constructor? No.
        // Alternative: we can call buyShares and sellShares to change state, but that might not change _QUOTE_RESERVE_ directly.
        // Simpler: Use the fact that the bug only manifests if quoteReserve > type(uint112).max.
        // We'll directly call adjustMtFeeRate with a vaild rate. The before/after check works if we can get _QUOTE_RESERVE_ before.
        // But to get before, we need a call that doesn't revert. Since _MAINTAINER_ is default address(0), only address(0) can call adjustMtFeeRate.
        // We'll prank as address(0). That's fine.
        uint256 beforeQuoteReserve = c._QUOTE_RESERVE_();
        vm.prank(address(0)); // _MAINTAINER_ is initial address(0)
        c.adjustMtFeeRate(mtFeeRate);
        uint256 afterQuoteReserve = c._QUOTE_RESERVE_();

        assertTrue(beforeQuoteReserve == afterQuoteReserve, "_QUOTE_RESERVE_ changed after adjustMtFeeRate");
    }
}

