pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        vm.assume(mtFeeRate <= 1e18);
        // Set reserves and open TWAP
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(1))); // _IS_OPEN_TWAP_ = true (slot 0)
        vm.store(address(c), bytes32(uint256(5)), bytes32(uint256(1e18))); // _BASE_RESERVE_ = 1e18 (slot 5)
        vm.store(address(c), bytes32(uint256(6)), bytes32(uint256(1e18))); // _QUOTE_RESERVE_ = 1e18 (slot 6)
        // Advance time
        vm.warp(block.timestamp + 1000);
        // Call adjustMtFeeRate – triggers _twapUpdate
        c.adjustMtFeeRate(mtFeeRate);
        // After the call, _BASE_PRICE_CUMULATIVE_LAST_ must be > 0
        uint256 cumulativePrice = uint256(vm.load(address(c), bytes32(uint256(8)))); // slot 8
        assertTrue(cumulativePrice > 0);
    }
}
